package schema

import (
	"fmt"
	"strings"
)

// TableNameMapper transforms a table name for use in DDL output.
type TableNameMapper func(originalName string) string

// ReconstructDDLForSchema builds schema-qualified CREATE TABLE statements.
// Tables, foreign key references, and indexes are qualified with targetSchema.
// Sequence-based defaults (nextval) are converted to GENERATED BY DEFAULT AS IDENTITY.
func ReconstructDDLForSchema(sg *SchemaGraph, targetSchema string) string {
	return ReconstructDDLForSchemaWithMapping(sg, targetSchema, nil)
}

// ReconstructDDLForSchemaWithMapping builds schema-qualified CREATE TABLE statements
// with an optional table name mapper. When mapper is non-nil, it is applied to table
// names in CREATE TABLE, FK REFERENCES, CREATE INDEX, and index name prefixes.
func ReconstructDDLForSchemaWithMapping(sg *SchemaGraph, targetSchema string, mapper TableNameMapper) string {
	mapName := func(n string) string {
		if mapper != nil {
			return mapper(n)
		}
		return n
	}

	var b strings.Builder

	fmt.Fprintf(&b, "CREATE SCHEMA IF NOT EXISTS %s;\n\n", quoteIdent(targetSchema))

	for _, t := range sg.Tables {
		mappedName := mapName(t.Name)
		qualifiedTable := quoteIdent(targetSchema) + "." + quoteIdent(mappedName)
		fmt.Fprintf(&b, "CREATE TABLE IF NOT EXISTS %s (\n", qualifiedTable)

		for i, c := range t.Columns {
			defaultVal := c.DefaultValue
			isIdentity := false
			// Convert nextval(...) defaults to GENERATED BY DEFAULT AS IDENTITY
			if strings.Contains(defaultVal, "nextval(") {
				isIdentity = true
				defaultVal = ""
			}

			fmt.Fprintf(&b, "    %s %s", quoteIdent(c.Name), c.DataType)
			if isIdentity {
				b.WriteString(" GENERATED BY DEFAULT AS IDENTITY")
			}
			if !c.IsNullable {
				b.WriteString(" NOT NULL")
			}
			if defaultVal != "" {
				fmt.Fprintf(&b, " DEFAULT %s", defaultVal)
			}
			if i < len(t.Columns)-1 || len(t.PrimaryKey) > 0 || len(t.ForeignKeys) > 0 || len(t.Checks) > 0 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}

		if len(t.PrimaryKey) > 0 {
			quoted := make([]string, len(t.PrimaryKey))
			for i, pk := range t.PrimaryKey {
				quoted[i] = quoteIdent(pk)
			}
			fmt.Fprintf(&b, "    PRIMARY KEY (%s)", strings.Join(quoted, ", "))
			if len(t.ForeignKeys) > 0 || len(t.Checks) > 0 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}

		for i, fk := range t.ForeignKeys {
			cols := make([]string, len(fk.Columns))
			refCols := make([]string, len(fk.ReferencedCols))
			for j := range fk.Columns {
				cols[j] = quoteIdent(fk.Columns[j])
				refCols[j] = quoteIdent(fk.ReferencedCols[j])
			}
			mappedRef := mapName(fk.ReferencedTable)
			qualifiedRef := quoteIdent(targetSchema) + "." + quoteIdent(mappedRef)
			fmt.Fprintf(&b, "    FOREIGN KEY (%s) REFERENCES %s (%s)",
				strings.Join(cols, ", "), qualifiedRef, strings.Join(refCols, ", "))
			if i < len(t.ForeignKeys)-1 || len(t.Checks) > 0 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}

		for i, ck := range t.Checks {
			fmt.Fprintf(&b, "    CONSTRAINT %s CHECK (%s)", quoteIdent(ck.Name), ck.Expression)
			if i < len(t.Checks)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}

		b.WriteString(");\n\n")
	}

	// Create indexes with schema-qualified table names
	for _, t := range sg.Tables {
		mappedName := mapName(t.Name)
		for _, idx := range t.Indexes {
			qualifiedTable := quoteIdent(targetSchema) + "." + quoteIdent(mappedName)
			qualifiedIdx := quoteIdent(mapName(idx.Name))
			cols := make([]string, len(idx.Columns))
			for i, c := range idx.Columns {
				cols[i] = quoteIdent(c)
			}
			unique := ""
			if idx.IsUnique {
				unique = "UNIQUE "
			}
			fmt.Fprintf(&b, "CREATE %sINDEX IF NOT EXISTS %s ON %s (%s);\n",
				unique, qualifiedIdx, qualifiedTable, strings.Join(cols, ", "))
		}
	}

	return b.String()
}

func quoteIdent(s string) string {
	// Simple quoting — only quote if needed
	if needsQuoting(s) {
		return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
	}
	return s
}

func needsQuoting(s string) bool {
	for i, c := range s {
		if i == 0 {
			if !((c >= 'a' && c <= 'z') || c == '_') {
				return true
			}
		} else {
			if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
				return true
			}
		}
	}
	return false
}
